import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.HashMap;
import java.util.NoSuchElementException;
import java.util.StringTokenizer;

public class G5 {

    static class IntList {
        int data[] = new int[3];
        int size = 0;

        boolean isEmpty() {
            return size == 0;
        }

        int size() {
            return size;
        }

        int get(int index) {
            if (index < 0 || index >= size) {
                throw new IndexOutOfBoundsException();
            }
            return data[index];
        }

        void clear() {
            size = 0;
        }

        void set(int index, int value) {
            if (index < 0 || index >= size) {
                throw new IndexOutOfBoundsException();
            }
            data[index] = value;
        }

        void expand() {
            if (size >= data.length) {
                data = Arrays.copyOf(data, (data.length << 1) + 1);
            }
        }

        void insert(int index, int value) {
            if (index < 0 || index > size) {
                throw new IndexOutOfBoundsException();
            }
            expand();
            System.arraycopy(data, index, data, index + 1, size++ - index);
            data[index] = value;
        }

        int delete(int index) {
            if (index < 0 || index >= size) {
                throw new IndexOutOfBoundsException();
            }
            int value = data[index];
            System.arraycopy(data, index + 1, data, index, --size - index);
            return value;
        }

        void push(int value) {
            expand();
            data[size++] = value;
        }

        int pop() {
            if (size == 0) {
                throw new NoSuchElementException();
            }
            return data[--size];
        }

        void unshift(int value) {
            expand();
            System.arraycopy(data, 0, data, 1, size++);
            data[0] = value;
        }

        int shift() {
            if (size == 0) {
                throw new NoSuchElementException();
            }
            int value = data[0];
            System.arraycopy(data, 1, data, 0, --size);
            return value;
        }
    }

    static class Frame {
        int from, to, state;
        IntList left, right, result;

        Frame(int from, int to) {
            this.from = from;
            this.to = to;
        }
    }

    static int n, m;

    static IntList buildBase(int from) {
        IntList res = new IntList();
        res.push(from);
        if (from + m > n) {
            res.push(n - from);
            res.push(from - n);
        }
        res.push(m);
        if (from > m) {
            res.push(n - from);
            res.push(from);
        }
        res.push(-from);
        return res;
    }

    static IntList merge(IntList a, IntList b) {
        IntList res = new IntList();
        int aSize = a.size;
        int bSize = b.size;
        int aData[] = a.data;
        int bData[] = b.data;
        for (int i = 0;; i += 2) {
            int bFrom = i == 0 ? 0 : bData[i - 1];
            int bTo = i == bSize - 1 ? n : bData[i + 1];
            int bShift = bData[i];
            int aFrom = bFrom + bShift;
            int aTo = bTo + bShift;
            int l = 0;
            int r = aSize - 1;
            while (l < r) {
                int m = (((l + r) >> 2) << 1) + 1;
                if (aData[m] <= aFrom) {
                    l = m + 1;
                } else {
                    r = m - 1;
                }
            }
            int cur = l;
            while (true) {
                res.push(bShift + aData[cur]);
                ++cur;
                if (cur == aSize) {
                    break;
                }
                int pos = aData[cur];
                if (pos >= aTo) {
                    break;
                }
                res.push(pos - bShift);
                ++cur;
            }
            if (i == bSize - 1) {
                break;
            }
            res.push(bTo);
        }
        return res;
    }

    static IntList solve(int from, int to) {
        Deque<Frame> stack = new ArrayDeque<Frame>();
        stack.push(new Frame(from, to));
        while (!stack.isEmpty()) {
            Frame f = stack.peek();
            if (f.state == 2) {
                f.result = merge(f.left, f.right);
                stack.pop();
                if (stack.isEmpty()) {
                    return f.result;
                }
                Frame p = stack.peek();
                p.state++;
                if (p.state == 1) {
                    p.left = f.result;
                } else {
                    p.right = f.result;
                }
                continue;
            }
            if (f.from + 1 == f.to) {
                f.result = buildBase(f.from);
                stack.pop();
                if (stack.isEmpty()) {
                    return f.result;
                }
                Frame p = stack.peek();
                p.state++;
                if (p.state == 1) {
                    p.left = f.result;
                } else {
                    p.right = f.result;
                }
                continue;
            }
            if (f.state == 0) {
                int mid = (f.from + f.to) >> 1;
                stack.push(new Frame(mid, f.to));
                stack.push(new Frame(f.from, mid));
                continue;
            }
            continue;
        }
        return null;
    }

    static void solve() throws Exception {
        n = scanInt();
        m = scanInt();
        int s = scanInt() - 1;
        long t = scanLong();
        for (int ct = (int) (t % n); ct != 0; ct--) {
            if (s < m) {
                s += ct;
                if (s >= n) {
                    s -= n;
                }
            } else {
                s -= ct;
                if (s < 0) {
                    s += n;
                }
            }
        }
        long cycles = t / n;
        if (cycles > 0) {
            IntList cycleSolve = solve(0, n);
            int csSize = cycleSolve.size;
            int csData[] = cycleSolve.data;
            IntList cycleList = new IntList();
            HashMap<Integer, Integer> cycleMap = new HashMap<Integer, Integer>();
            for (int it = 0;; it++) {
                if (it == cycles) {
                    break;
                }
                Integer prevObj = cycleMap.get(s);
                int prev = prevObj == null ? -1 : prevObj.intValue();
                if (prev >= 0) {
                    s = cycleList.get(prev + (int) ((cycles - prev) % (it - prev)));
                    break;
                }
                cycleList.push(s);
                cycleMap.put(s, it);
                int l = 0;
                int r = csSize - 1;
                while (l < r) {
                    int m = (((l + r) >> 2) << 1) + 1;
                    if (csData[m] <= s) {
                        l = m + 1;
                    } else {
                        r = m - 1;
                    }
                }
                s += csData[l];
            }
        }
        out.print(s + 1);
    }

    static int scanInt() throws IOException {
        return Integer.parseInt(scanString());
    }

    static long scanLong() throws IOException {
        return Long.parseLong(scanString());
    }

    static String scanString() throws IOException {
        while (tok == null || !tok.hasMoreTokens()) {
            tok = new StringTokenizer(in.readLine());
        }
        return tok.nextToken();
    }

    static BufferedReader in;
    static PrintWriter out;
    static StringTokenizer tok;

    public static void main(String[] args) {
        try {
            in = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out);
            solve();
            in.close();
            out.close();
        } catch (Throwable e) {
            e.printStackTrace();
            System.exit(1);
        }
    }
}
